import { LOCAL_RACES_DATA } from './local-races-data';

export type Party = 'DEM' | 'REP' | 'IND' | 'LIB' | 'GRN' | 'NP' | 'WFP' | 'CON';
export type CandidateStatus = 'Incumbent' | 'Challenger' | 'Open Seat' | 'Primary Winner' | 'Write-In' | 'Declared';

export interface CandidateSourceVerification {
  agency: string;
  filingId: string;
  filingDate: string;
  verificationStatus: string;
  sourceUrl?: string;
}

export interface Candidate {
  name: string;
  party: Party;
  status: CandidateStatus;
  priorOffice?: string;
  cashOnHandMillions?: number;
  website?: string;
  age?: number;
  hometown?: string;
  pollShare?: number;
  biography?: string;
  platformStance?: string;
  sourceVerification?: CandidateSourceVerification;
}

export interface VerifiedSource {
  title: string;
  sourceType: string;
  url: string;
  lastChecked: string;
}

export interface RaceEntry {
  raceId: string;
  level: 'federal' | 'state' | 'county' | 'municipal' | 'special_district' | 'judicial';
  office: string;
  state: string;
  stateAbbr: string;
  county?: string;
  municipality?: string;
  city?: string;
  district?: string;
  electionDate: string;
  isPartisan: boolean;
  cookRating?: string;
  pollAverage?: string | null;
  pollingMethod?: string | null;
  qualifyingPollsCount?: number;
  candidateStatus?: string;
  totalFundraisingM?: number;
  candidates: Candidate[];
  keyIssues?: string[];
  notes?: string;
  population?: number;
  verifiedSources?: VerifiedSource[];
  lastUpdated?: string;
}

